fn g32(v:&mut[u32;16],a:usize,b:usize,c:usize,d:usize,x:u32,y:u32){v[a]=v[a].wrapping_add(v[b]).wrapping_add(x);v[d]=(v[d]^v[a]).rotate_right(16);v[c]=v[c].wrapping_add(v[d]);v[b]=(v[b]^v[c]).rotate_right(12);v[a]=v[a].wrapping_add(v[b]).wrapping_add(y);v[d]=(v[d]^v[a]).rotate_right(8);v[c]=v[c].wrapping_add(v[d]);v[b]=(v[b]^v[c]).rotate_right(7);}
fn g64(v:&mut[u64;16],a:usize,b:usize,c:usize,d:usize,x:u64,y:u64){v[a]=v[a].wrapping_add(v[b]).wrapping_add(x);v[d]=(v[d]^v[a]).rotate_right(32);v[c]=v[c].wrapping_add(v[d]);v[b]=(v[b]^v[c]).rotate_right(25);v[a]=v[a].wrapping_add(v[b]).wrapping_add(y);v[d]=(v[d]^v[a]).rotate_right(16);v[c]=v[c].wrapping_add(v[d]);v[b]=(v[b]^v[c]).rotate_right(11);}
struct B256{h:[u32;8],t:[u32;2],buf:[u8;64],n:u32,null:bool}
