fn comp(&mut self,b:&[u8]){let mut m=[0u32;16];for i in 0..16{m[i]=u32::from_be_bytes(b[4*i..4*i+4].try_into().unwrap())}let mut v=[0u32;16];v[..8].copy_from_slice(&self.h);v[8..].copy_from_slice(&[C32[0],C32[1],C32[2],C32[3],C32[4],C32[5],C32[6],C32[7]]);if !self.null{v[12]^=self.t[0];v[13]^=self.t[0];v[14]^=self.t[1];v[15]^=self.t[1]}for r in 0..14{let s=&S[r%10];g32(&mut v,0,4,8,12,m[s[0]]^C32[s[1]],m[s[1]]^C32[s[0]]);g32(&mut v,1,5,9,13,m[s[2]]^C32[s[3]],m[s[3]]^C32[s[2]]);g32(&mut v,2,6,10,14,m[s[4]]^C32[s[5]],m[s[5]]^C32[s[4]]);g32(&mut v,3,7,11,15,m[s[6]]^C32[s[7]],m[s[7]]^C32[s[6]]);g32(&mut v,0,5,10,15,m[s[8]]^C32[s[9]],m[s[9]]^C32[s[8]]);g32(&mut v,1,6,11,12,m[s[10]]^C32[s[11]],m[s[11]]^C32[s[10]]);g32(&mut v,2,7,8,13,m[s[12]]^C32[s[13]],m[s[13]]^C32[s[12]]);g32(&mut v,3,4,9,14,m[s[14]]^C32[s[15]],m[s[15]]^C32[s[14]])}for i in 0..8{self.h[i]^=v[i]^v[i+8]}}
fn up(&mut self,d:&[u8],mut bits:u64){let mut p=0;let mut left=(self.n>>3)as usize;let fill=64-left;if left!=0&&(((bits>>3)as usize&63)>=fill){self.buf[left..].copy_from_slice(&d[..fill]);let(x,_)=self.t[0].overflowing_add(512);self.t[0]=x;if x==0{self.t[1]=self.t[1].wrapping_add(1)}let b=self.buf;self.comp(&b);p+=fill;bits-=(fill as u64)<<3;left=0}while bits>=512{let(x,_)=self.t[0].overflowing_add(512);self.t[0]=x;if x==0{self.t[1]=self.t[1].wrapping_add(1)}self.comp(&d[p..p+64]);p+=64;bits-=512}if bits>0{let q=(bits>>3)as usize;self.buf[left..left+q].copy_from_slice(&d[p..p+q]);self.n=((left as u32)<<3).wrapping_add(bits as u32)}else{self.n=0}}
